import pytest
from enum import Enum
import marshmallow as ma
from marshmallow import Schema, fields, ValidationError

class MyEnum(Enum):
    A = "a"
    NONE = None

def test_enum_with_none_value_by_value():
    class S(Schema):
        sentinel = fields.Enum(MyEnum, by_value=True)

    data = {"sentinel": None}
    result = S().load(data)
    assert result["sentinel"] == MyEnum.NONE

